import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class MakeDeclaredNamesUnique_visit_TriageGen1Test {

  @Mock private NodeTraversal mockTraversal;
  @Mock private Compiler mockCompiler;
  @Mock private Renamer mockRenamer;
  @Mock private Node mockNode;

  private MakeDeclaredNamesUnique renamerUnderTest;
  private Stack<Renamer> nameStack;

  // Mock Renamer class as it is used internally via nameStack
  public interface Renamer {
    boolean stripConstIfReplaced();
  }

  @Before
  public void setUp() throws Exception {
    MockitoAnnotations.initMocks(this);
    renamerUnderTest = new MakeDeclaredNamesUnique();
    nameStack = new Stack<>();

    // Inject the nameStack field using reflection since it's likely private
    FieldSetter.setField(renamerUnderTest, 
        renamerUnderTest.getClass().getDeclaredField("nameStack"), nameStack);

    when(mockTraversal.getCompiler()).thenReturn(mockCompiler);
  }

  @Test
  public void testVisit_Name_WithReplacement_AndStripConst() {
    // Setup: Token.NAME, replacement found, stripConst returns true
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.NAME, "oldName");
    nameStack.push(mockRenamer());
    when(mockRenamer().getReplacementName("oldName")).thenReturn("newName");
    when(mockRenamer().stripConstIfReplaced()).thenReturn(true);

    // We need to mock the getReplacementName logic. 
    // Since we can't easily override the internal method of the class under test 
    // without Spying, we assume the behavior is driven by the internal state.
    // However, for the sake of this unit test, we will spy on the class to control getReplacementName.
    MakeDeclaredNamesUnique spyUnderTest = org.mockito.Mockito.spy(renamerUnderTest);
    org.mockito.Mockito.doReturn("newName").when(spyUnderTest).getReplacementName("oldName");
    org.mockito.Mockito.doReturn(mockRenamer()).when(spyUnderTest).getNameStack(); 
    // Note: If nameStack is private, we rely on the FieldSetter used in setUp.

    spyUnderTest.visit(mockTraversal, n, null);

    assertEquals("newName", n.getString());
    assertEquals(false, n.isProp(Node.IS_CONSTANT_NAME));
    verify(mockCompiler).reportCodeChange();
  }

  @Test
  public void testVisit_Name_WithReplacement_AndNoStripConst() {
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.NAME, "oldName");
    n.setProperty(Node.IS_CONSTANT_NAME, true);
    nameStack.push(mockRenamer());

    MakeDeclaredNamesUnique spyUnderTest = org.mockito.Mockito.spy(renamerUnderTest);
    org.mockito.Mockito.doReturn("newName").when(spyUnderTest).getReplacementName("oldName");

    when(mockRenamer().stripConstIfReplaced()).thenReturn(false);

    spyUnderTest.visit(mockTraversal, n, null);

    assertEquals("newName", n.getString());
    assertEquals(true, n.isProp(Node.IS_CONSTANT_NAME));
    verify(mockCompiler).reportCodeChange();
  }

  @Test
  public void testVisit_Name_NoReplacement() {
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.NAME, "oldName");

    MakeDeclaredNamesUnique spyUnderTest = org.mockito.Mockito.spy(renamerUnderTest);
    org.mockito.Mockito.doReturn(null).when(spyUnderTest).getReplacementName("oldName");

    spyUnderTest.visit(mockTraversal, n, null);

    assertEquals("oldName", n.getString());
    verify(mockCompiler, never()).reportCodeChange();
  }

  @Test
  public void testVisit_Function_PopsStack() {
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.FUNCTION);
    nameStack.push(mockRenamer());
    nameStack.push(mockRenamer());

    renamerUnderTest.visit(mockTraversal, n, null);

    assertEquals(1, nameStack.size());
  }

  @Test
  public void testVisit_Catch_PopsStack() {
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.CATCH);
    nameStack.push(mockRenamer());
    nameStack.push(mockRenamer());

    renamerUnderTest.visit(mockTraversal, n, null);

    assertEquals(1, nameStack.size());
  }

  @Test
  public void testVisit_OtherToken_DoesNothing() {
    Node n = makeGuardedNode(com.google.javascript.Rhino.Token.COMMA);
    nameStack.push(mockRenamer());

    renamerUnderTest.visit(mockTraversal, n, null);

    assertEquals(1, nameStack.size());
    verify(mockCompiler, never()).reportCodeChange();
  }

  private Renamer mockRenamer() {
    return mockRenamer;
  }
}
